  {"nr":1,"grundpfeiler":null,"saeule":null,"titel":"Nutzt Leerlaufzeiten sinnvoll (z. B. Aufräumen, Vorbereiten).","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, Leerlaufzeiten bewusster wahrzunehmen und sinnvoll zu nutzen.","punkte":["entwickelt ein erstes Gefühl für freie Zeit im Arbeitsalltag","erkennt zunehmend Möglichkeiten für kleine Aufgaben","nutzt Leerlaufphasen gelegentlich für Ordnung oder Vorbereitung","versteht den Mehrwert sinnvoll genutzter Zeit für den Ablauf im Salon"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Nutzt Leerlaufzeiten in vielen Situationen bewusst und baut erste Routinen auf.","punkte":["nutzt freie Momente häufiger für Aufräumen oder Vorbereitung","achtet zunehmend auf Ordnung im eigenen Arbeitsbereich","übernimmt erste vorbereitende Tätigkeiten","entwickelt mehr Eigeninitiative in ruhigen Phasen"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Nutzt Leerlaufzeiten regelmäßig sinnvoll und eigenständig.","punkte":["verwendet freie Zeit konsequent für sinnvolle Aufgaben","sorgt für Ordnung und Vorbereitung im eigenen Bereich","erkennt selbstständig, was gerade zu tun ist","unterstützt damit einen strukturierten und reibungslosen Ablauf"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Geht vorausschauend mit Leerlaufzeiten um und bereitet Abläufe aktiv vor.","punkte":["erkennt Leerlaufphasen frühzeitig und nutzt sie gezielt","denkt kommende Arbeitsschritte mit und bereitet sie vor","handelt eigenständig und ohne Aufforderung","sorgt durch sein Verhalten für Struktur und Ruhe im Arbeitsalltag"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Denkt Leerlaufzeiten über den eigenen Bereich hinaus und stärkt damit das gesamte Team.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","erkennt frühzeitig, wo im Salon Unterstützung oder Ordnung gebraucht wird","gleicht Leerlaufphasen im Team aktiv aus","unterstützt Kollegen situativ und selbstverständlich","sorgt für durchgehend klare, strukturierte und effiziente Abläufe"]}]},
  {"nr":2,"grundpfeiler":null,"saeule":null,"titel":"Übernimmt auch weniger attraktive Aufgaben im Arbeitsalltag selbstverständlich und verantwortungsbewusst.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, gemeinsame Aufgaben im Arbeitsalltag bewusster wahrzunehmen.","punkte":["entwickelt ein erstes Verständnis für gemeinsame Verantwortung im Team","erkennt zunehmend, dass auch weniger attraktive Aufgaben zum Alltag gehören","beteiligt sich gelegentlich an solchen Aufgaben","baut ein Bewusstsein für Fairness im Team auf"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Übernimmt weniger attraktive Aufgaben in vielen Situationen und gewinnt an Selbstverständlichkeit.","punkte":["beteiligt sich häufiger an gemeinsamen Aufgaben","zeigt Bereitschaft, Verantwortung im Alltag zu übernehmen","übernimmt Aufgaben teilweise eigenständig","entwickelt mehr Routine im Umgang mit solchen Tätigkeiten"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Übernimmt auch weniger attraktive Aufgaben zuverlässig und eigenständig.","punkte":["übernimmt Aufgaben unabhängig von Attraktivität","beteiligt sich konstant an gemeinsamen Pflichten","handelt verlässlich im Teamkontext","trägt zu einem fairen und ausgeglichenen Arbeitsalltag bei"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Handelt vorausschauend und übernimmt Verantwortung auch bei weniger sichtbaren Aufgaben.","punkte":["erkennt eigenständig, was im Hintergrund erledigt werden muss","übernimmt Aufgaben ohne Aufforderung und ohne Zögern","denkt über den eigenen Bereich hinaus","sorgt durch sein Verhalten für Verlässlichkeit und Struktur im Team"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Stärkt durch sein Verhalten eine Kultur, in der Verantwortung selbstverständlich geteilt wird.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","erkennt frühzeitig, wo im Team Unterstützung gebraucht wird","gleicht Aufgaben im Team aktiv aus","unterstützt Kollegen dabei, Verantwortung zu übernehmen","sorgt für eine klare, faire und selbstverständliche Aufgabenverteilung im Alltag"]}]},
  {"nr":3,"grundpfeiler":null,"saeule":null,"titel":"Unterstützt Kollegen aktiv und situativ passend im Arbeitsalltag.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, Auslastung im Team bewusster wahrzunehmen.","punkte":["entwickelt ein erstes Gefühl dafür, wann Kollegen Unterstützung brauchen","nimmt Belastung im Umfeld zunehmend wahr","bietet vereinzelt Hilfe an","baut ein Bewusstsein für Zusammenarbeit im Alltag auf"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Unterstützt Kollegen in vielen Situationen und gewinnt an Sicherheit.","punkte":["bietet häufiger Unterstützung an","übernimmt kleinere Aufgaben zur Entlastung","reagiert auf erkennbare Auslastung im Team","entwickelt mehr Aufmerksamkeit für Abläufe im Umfeld"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Unterstützt Kollegen regelmäßig und eigenständig im Arbeitsalltag.","punkte":["erkennt zuverlässig, wann Unterstützung sinnvoll ist","hilft aktiv und ohne Aufforderung","übernimmt Aufgaben situativ passend","trägt zu einem ruhigen und flüssigen Ablauf bei"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Handelt vorausschauend und entlastet Kollegen gezielt in intensiven Phasen.","punkte":["erkennt frühzeitig erhöhte Auslastung im Team","bietet Unterstützung passend und zum richtigen Zeitpunkt an","übernimmt eigenständig Aufgaben zur Entlastung","denkt Abläufe mit und stabilisiert den Arbeitsfluss aktiv"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Sorgt für ein ausgeglichenes Arbeiten im Team und stärkt die Zusammenarbeit aktiv.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","erkennt frühzeitig, wo im Team Unterstützung benötigt wird","gleicht Belastungen im Team aktiv aus","unterstützt mehrere Kollegen situativ und selbstverständlich","trägt zu einer klaren, unterstützenden und stabilen Teamdynamik bei"]}]},
  {"nr":4,"grundpfeiler":null,"saeule":null,"titel":"Handelt im Arbeitsalltag bewusst im Sinne unserer Salon-Kultur und des Gästeerlebnisses.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt zu verstehen, wie das eigene Verhalten das Erlebnis für Gäste und das Team beeinflusst.","punkte":["entwickelt ein erstes Verständnis für unsere Werte und Haltung","erkennt, dass Verhalten das Erlebnis im Salon prägt","reflektiert das eigene Auftreten im Alltag","orientiert sich zunehmend an gemeinsamen Standards"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Richtet sein Verhalten in vielen Situationen bewusst an unserer Salon-Kultur aus.","punkte":["zeigt häufig ein Verhalten, das zu unseren Werten passt","achtet bewusster auf den Umgang mit Gästen und Kollegen","orientiert sich an den vereinbarten Standards","entwickelt Sicherheit im Auftreten im Sinne des Salons"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Handelt konstant im Sinne unserer Salon-Kultur und trägt zum Erlebnis bei.","punkte":["trifft Entscheidungen im Einklang mit unseren Werten","zeigt ein stimmiges Verhalten im Umgang mit Gästen und Kollegen","hält Standards zuverlässig ein","trägt zu einer klaren, ruhigen und hochwertigen Atmosphäre bei"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Handelt bewusst und versteht, dass Verhalten direkt den wahrgenommenen Wert des Salons beeinflusst.","punkte":["richtet sein Verhalten klar am Gästeerlebnis aus","trifft auch in anspruchsvollen Situationen bewusste Entscheidungen","wahrt Professionalität unabhängig von äußeren Umständen","sorgt aktiv dafür, dass unsere Kultur im Alltag sichtbar wird"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Versteht Verhalten als entscheidenden Faktor für Erlebnis, Bindung und Preis – und handelt konsequent danach.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","handelt jederzeit im Sinne des Gesamterlebnisses","gibt Orientierung durch klares und konsequentes Verhalten","stärkt aktiv das Verständnis im Team für Kultur und Wirkung","sorgt dafür, dass unsere Salon-Kultur im Alltag klar erlebbar bleibt"]}]},
  {"nr":5,"grundpfeiler":null,"saeule":null,"titel":"Zeigt im Arbeitsalltag eine konstante Einsatzbereitschaft und eine stabile, verlässliche Präsenz.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, die eigene Wirkung und Präsenz im Arbeitsalltag bewusster wahrzunehmen.","punkte":["entwickelt ein erstes Gefühl für die eigene Energie im Tagesverlauf","bringt sich in einzelnen Situationen bewusst ein","reflektiert das eigene Auftreten im Umgang mit Gästen und Kollegen","erkennt, dass Verhalten und Präsenz das Umfeld beeinflussen"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Zeigt in vielen Situationen Einsatzbereitschaft und gewinnt an Stabilität im Auftreten.","punkte":["bringt sich häufig aktiv in den Arbeitsalltag ein","arbeitet zunehmend gleichmäßiger über den Tag hinweg","bleibt in vielen Situationen ruhig und ansprechbar","entwickelt mehr Konstanz in Verhalten und Auftreten"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Zeigt eine konstante Einsatzbereitschaft und eine verlässliche Präsenz im Arbeitsalltag.","punkte":["arbeitet durchgehend aufmerksam und engagiert","bleibt auch bei höherer Auslastung stabil im Auftreten","reagiert ruhig und kontrolliert auf Veränderungen im Ablauf","sorgt für Verlässlichkeit und Kontinuität im Team"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Hält eine stabile, professionelle Präsenz – unabhängig von äußeren Umständen.","punkte":["bleibt auch in stressigen oder unklaren Situationen ruhig und fokussiert","zeigt eine gleichmäßige, kontrollierte Arbeitsweise","wirkt konstant ansprechbar und präsent für Gäste und Kollegen","trägt aktiv zu einer ruhigen und stabilen Atmosphäre bei"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Setzt durch seine stabile Präsenz und konstante Einsatzbereitschaft einen Maßstab im Team.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","bleibt auch in herausfordernden Phasen konstant ruhig und klar","stabilisiert durch sein Verhalten das Umfeld und den Ablauf","gibt Orientierung durch verlässliche Präsenz und Haltung","sorgt für ein gleichbleibend professionelles Niveau im gesamten Team"]}]},
  {"nr":6,"grundpfeiler":null,"saeule":null,"titel":"Übernimmt die Gesprächsführung bewusst, richtet sich nach dem Bedarf des Gastes und sorgt für eine ruhige, fokussierte Atmosphäre.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, Gespräche im Arbeitsalltag bewusster wahrzunehmen.","punkte":["entwickelt ein erstes Gefühl dafür, wie unterschiedlich Gäste kommunizieren möchten","bringt sich bewusster in Gespräche ein","stellt erste gezielte Fragen","erkennt zunehmend, dass Kommunikation das Erlebnis im Salon beeinflusst"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Gestaltet Gespräche in vielen Situationen bewusster und achtet auf den Gast.","punkte":["stellt häufiger passende Fragen zur Gesprächsbereitschaft","richtet den Fokus zunehmend auf den Gast","erkennt erste Unterschiede zwischen Gesprächsbedarf und Ruhebedürfnis","entwickelt mehr Gefühl für Timing im Gespräch"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Führt Gespräche situationsgerecht und mit klarem Fokus auf den Gast.","punkte":["erkennt, ob der Gast sprechen, lesen oder für sich sein möchte","passt die Kommunikation entsprechend an","hält Gespräche ruhig, klar und zielgerichtet","nutzt Gespräche bewusst für relevante Inhalte (z. B. Ablauf, Produkte)"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Steuert Kommunikation bewusst und schafft eine ruhige, hochwertige Atmosphäre.","punkte":["wählt gezielt zwischen Gespräch und bewusster Ruhe","hält die Lautstärke im Arbeitsumfeld kontrolliert und angenehm","erklärt Arbeitsschritte und Produkte klar und passend","schafft durch Kommunikation Fokus, Ruhe und Professionalität"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Schafft durch intuitive und präzise Gesprächsführung ein besonders stimmiges und hochwertiges Gästeerlebnis.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","erkennt unmittelbar, welche Form der Kommunikation der Gast braucht","wechselt mühelos zwischen Gespräch, Erklärung und bewusster Ruhe","setzt Worte gezielt und reduziert ein – ohne unnötige Kommunikation","schafft eine Atmosphäre, in der sich der Gast gleichzeitig betreut und vollkommen entspannt fühlt"]}]},
  {"nr":7,"grundpfeiler":null,"saeule":null,"titel":"Spricht und kommuniziert so, dass sich der Gast jederzeit einbezogen und verstanden fühlt.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, die Wirkung von Sprache auf das Gefühl des Gastes bewusster wahrzunehmen.","punkte":["entwickelt ein erstes Verständnis dafür, dass Sprache Zugehörigkeit schafft","erkennt, dass unverständliche Kommunikation den Gast ausschließen kann","achtet gelegentlich darauf, den Gast einzubeziehen","reflektiert eigene Kommunikation im Arbeitsalltag"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Kommuniziert in vielen Situationen bewusst so, dass der Gast folgen kann.","punkte":["spricht im Kundenkontakt überwiegend klar und verständlich","achtet häufiger darauf, den Gast einzubeziehen","reduziert interne oder schwer verständliche Kommunikation","entwickelt mehr Sicherheit im sprachlichen Umgang mit Gästen"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Sorgt durch klare und bewusste Sprache für ein durchgehend verständliches Erlebnis.","punkte":["spricht im Kundenkontakt konsequent verständlich (z. B. auf Deutsch)","hält Kommunikation für den Gast nachvollziehbar","nutzt andere Sprachen im Arbeitsalltag nur situativ und dezent","sorgt dafür, dass der Gast sich jederzeit eingebunden fühlt"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Steuert Sprache bewusst so, dass der Gast vollständig integriert bleibt.","punkte":["wählt Sprache konsequent im Sinne des Gastes","integriert interne Kommunikation unauffällig und ohne Ausgrenzung","erklärt Inhalte klar und verständlich","sorgt für ein Gefühl von Sicherheit und Zugehörigkeit beim Gast"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Schafft durch bewusste und präzise Kommunikation ein besonders klares und inklusives Gästeerlebnis.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","erkennt sofort, wenn Kommunikation für den Gast unklar werden könnte","passt Sprache und Ausdruck intuitiv an","vermeidet jede Form von Ausgrenzung durch Kommunikation","sorgt dafür, dass sich der Gast jederzeit vollständig verstanden und einbezogen fühlt"]}]},
  {"nr":8,"grundpfeiler":null,"saeule":null,"titel":"Spricht den Gast bewusst und angemessen mit Namen an und schafft dadurch persönliche Nähe mit Stil.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, die Wirkung persönlicher Ansprache bewusster wahrzunehmen.","punkte":["entwickelt ein erstes Gefühl für den Einsatz des Namens","integriert den Namen situativ in den Kontakt","erkennt, dass persönliche Ansprache die Beziehung stärkt","baut Sicherheit im Umgang mit Namen auf"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Setzt den Namen in vielen Situationen bewusst ein und gewinnt an Selbstverständlichkeit.","punkte":["begrüßt und verabschiedet häufig mit Namen","integriert den Namen zunehmend im Gespräch","achtet mehr auf passende Momente","entwickelt ein Gefühl für eine angenehme und natürliche Ansprache"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Verwendet den Namen konstant und situationsgerecht im Arbeitsalltag.","punkte":["nutzt den Namen in passenden Momenten selbstverständlich","vermeidet Überbetonung oder Wiederholungen","wirkt aufmerksam und persönlich","sorgt für eine natürliche und angenehme Ansprache","bereitet sich auf den Gast vor (z. B. kennt den Namen vor dem Kontakt)"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Setzt Namensansprache gezielt und bewusst als Teil des Service ein.","punkte":["nutzt den Namen sicher im persönlichen Kontakt und am Telefon","wählt Zeitpunkt und Häufigkeit bewusst","verbindet Ansprache mit ruhiger Präsenz und klarer Struktur","schafft durch gezielte Ansprache Aufmerksamkeit und Wertschätzung"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Schafft durch präzise und fein dosierte Ansprache eine besonders persönliche und hochwertige Verbindung.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","erkennt intuitiv, wann und wie der Name wirkungsvoll eingesetzt wird","setzt den Namen gezielt und zurückhaltend ein","schafft eine spürbare persönliche Verbindung ohne Aufdringlichkeit","sorgt dafür, dass sich der Gast individuell wahrgenommen und wertgeschätzt fühlt"]}]},
  {"nr":9,"grundpfeiler":null,"saeule":null,"titel":"Informiert den Gast bei jedem Arbeitsschritt über verwendete Produkte, Tools und Dienstleistungen.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, die Wirkung von Erklärungen im Service bewusster wahrzunehmen.","punkte":["nennt Produkte oder Schritte situativ im Ablauf","erklärt einzelne Handgriffe in passenden Momenten","entwickelt ein erstes Gefühl für Struktur im Service","erkennt, dass Erklärungen Vertrauen schaffen"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Integriert Erklärungen in viele Arbeitsschritte und gewinnt an Sicherheit.","punkte":["nennt Produkte und Abläufe häufiger aktiv","erklärt Wirkung zunehmend verständlich","bindet den Gast mehr in den Ablauf ein","entwickelt mehr Sicherheit in der fachlichen Kommunikation"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Erklärt Arbeitsschritte und Produkte konstant verständlich und nachvollziehbar.","punkte":["beschreibt Produkte, Tools und Abläufe klar und ruhig","erklärt Wirkung und Anwendung verständlich","gibt dem Gast Orientierung im Ablauf","schafft Sicherheit durch nachvollziehbare Informationen"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Strukturiert den Ablauf bewusst und vermittelt Kompetenz klar und ruhig.","punkte":["erklärt Auswahl und Ziel der Produkte verständlich","führt den Gast strukturiert durch den gesamten Ablauf","nutzt klare und einheitliche Sprache","vermittelt Fachwissen ruhig und ohne Verkaufsdruck","schafft ein Gefühl von Professionalität und Vertrauen"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Schafft durch präzise und verständliche Erklärungen ein besonders hochwertiges und sicheres Erlebnis.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","stellt Zusammenhänge zwischen Haarzustand, Produkten und Ergebnis klar dar","erklärt Wirkung und Langzeiteffekte verständlich und relevant","passt Tiefe und Umfang der Erklärungen intuitiv an den Gast an","sorgt dafür, dass sich der Gast sicher, verstanden und optimal betreut fühlt"]}]},
  {"nr":10,"grundpfeiler":null,"saeule":null,"titel":"Erfasst relevante Gästeinformationen bewusst und nutzt sie, um ein persönliches und vorbereitetes Gästeerlebnis zu schaffen.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, Gästeinformationen als Teil eines persönlichen Service zu erkennen.","punkte":["nimmt Details zum Gast bewusster wahr","hält einzelne Informationen situativ fest","erkennt erste Zusammenhänge zwischen Notizen und Service","entwickelt ein Gefühl für persönliche Ansprache"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Erfasst Gästeinformationen in vielen Situationen bewusst und nutzt sie zunehmend.","punkte":["hält Wünsche und Besonderheiten häufiger fest","greift gespeicherte Informationen im Ablauf auf","erkennt den Mehrwert für den Service","entwickelt mehr Struktur im Umgang mit Informationen"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Arbeitet zuverlässig mit Gästeinformationen und nutzt sie aktiv im Service.","punkte":["hält Informationen klar und nachvollziehbar fest","nutzt vorhandene Daten im Kontakt mit dem Gast","vermeidet unnötige Wiederholungsfragen","wirkt vorbereitet und aufmerksam"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Nutzt Gästeinformationen gezielt, um ein persönliches und hochwertiges Erlebnis zu schaffen.","punkte":["dokumentiert präzise und vollständig","bereitet sich bewusst auf den Termin vor","nutzt Informationen für eine persönliche Ansprache","schafft einen strukturierten und durchdachten Ablauf","sorgt dafür, dass sich der Gast wiedererkannt fühlt"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Schafft durch gezielte Nutzung von Informationen eine besonders persönliche und nachhaltige Verbindung.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","erkennt, welche Details für den Gast wirklich relevant sind","nutzt Informationen gezielt und situationsgerecht","schafft Wiedererkennung über mehrere Besuche hinweg","sorgt dafür, dass sich der Gast individuell wahrgenommen und langfristig verbunden fühlt"]}]},
  {"nr":11,"grundpfeiler":null,"saeule":null,"titel":"Fragt Gäste regelmäßig und passend nach Feedback (z. B. Google).","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, Feedback als natürlichen Teil des Austauschs mit dem Gast zu verstehen.","punkte":["entwickelt ein erstes Verständnis dafür, dass Feedback Unterstützung ist","erkennt, dass ehrliches Feedback zur Weiterentwicklung beiträgt","überwindet erste Unsicherheiten in der Ansprache","spricht Feedback vereinzelt in passenden Momenten an","löst sich zunehmend von dem Gefühl, „nach etwas zu fragen“"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Fragt in vielen Situationen nach Feedback und gewinnt Sicherheit in der Ansprache.","punkte":["nutzt passende Momente im Abschluss häufiger bewusst","formuliert Feedback als Einladung statt als Bitte","entwickelt ein Gefühl dafür, wie es sich natürlich integrieren lässt","merkt, dass Gäste positiv auf die Ansprache reagieren","gewinnt Sicherheit, Feedback offen anzusprechen"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Integriert Feedback konstant und selbstverständlich in den Ablauf.","punkte":["erkennt emotionale Hochmomente beim Gast","fragt ruhig und passend nach Feedback","wirkt natürlich und sicher in der Ansprache","verbindet Feedback mit dem Erlebnis im Salon"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Integriert Feedback bewusst in den Serviceprozess und zeigt Wertschätzung im Umgang damit.","punkte":["wählt den richtigen Moment gezielt aus","erkennt, wann Feedback passend ist und wann nicht","dokumentiert, ob ein Gast bereits Feedback gegeben hat","vermeidet wiederholtes Nachfragen bewusst","nutzt vorhandene Informationen, um sich persönlich zu bedanken","vermittelt Feedback als Einladung und zeigt echte Wertschätzung dafür"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Schafft durch bewussten Umgang mit Feedback eine persönliche und nachhaltige Beziehung zum Gast.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","behält im Blick, welche Gäste bereits Feedback gegeben haben","bedankt sich gezielt und persönlich bei Gästen für ihr Feedback","nutzt kleine, passende Aufmerksamkeiten (z. B. Eye Care vom Azubi oder ähnliche Gesten)","sorgt dafür, dass sich der Gast gesehen und wertgeschätzt fühlt","integriert Feedback selbstverständlich in eine gelebte Beziehungskultur"]}]},
  {"nr":12,"grundpfeiler":null,"saeule":null,"titel":"Sorgt dafür, dass Gäste während der Behandlung durchgehend betreut sind und keine Unterbrechungen im Service entstehen.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, Unterbrechungen im eigenen Ablauf bewusst wahrzunehmen.","punkte":["erkennt, wann der eigene Fokus vom Gast abweicht","bemerkt Ablenkungen durch Kollegen, Telefon oder Umfeld","unterbricht die Behandlung noch situativ","entwickelt ein erstes Bewusstsein für durchgängige Betreuung"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Reduziert Unterbrechungen und richtet den Fokus zunehmend auf den Gast.","punkte":["bleibt häufiger beim Gast und unterbricht seltener","reagiert bewusster auf Ablenkungen im Umfeld","beginnt, den aktuellen Gast klar zu priorisieren","hält die Behandlung ruhiger und strukturierter"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Arbeitet überwiegend ohne Unterbrechungen und hält den Fokus konstant beim Gast.","punkte":["lässt sich während der Behandlung nicht ablenken","priorisiert den aktuellen Gast vor parallelen Themen","hält den Ablauf klar und konzentriert","sorgt für eine ruhige, durchgehende Behandlung"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Arbeitet konsequent ohne Unterbrechungen und zeigt klare Priorität für den Gast.","punkte":["bleibt während der gesamten Behandlung vollständig beim Gast","lässt sich weder durch Kollegen, Telefon noch andere Gäste ablenken","organisiert Abläufe so, dass Unterbrechungen vermieden werden","arbeitet strukturiert, ruhig und fokussiert","vermittelt durchgehend Präsenz und Kontrolle im Ablauf"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Verkörpert maximale Präsenz und setzt einen klaren Standard für fokussiertes Arbeiten.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","arbeitet durchgehend ohne wahrnehmbare Unterbrechungen","priorisiert den aktuellen Gast konsequent über alle parallelen Einflüsse","bleibt auch in dynamischen Situationen vollständig fokussiert","steht für eine Arbeitsweise, in der volle Aufmerksamkeit und Präsenz selbstverständlich sind"]}]},
  {"nr":13,"grundpfeiler":null,"saeule":null,"titel":"Erscheint mit gepflegten Haaren und einer ordentlichen, bewusst gewählten eigenen Frisur.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, die eigene Erscheinung als Teil der professionellen Wirkung zu verstehen.","punkte":["entwickelt ein erstes Bewusstsein für die Wirkung der eigenen Frisur","erkennt, dass äußere Erscheinung Einfluss auf Wahrnehmung hat","achtet gelegentlich auf ein gepflegtes Auftreten","beginnt, sich bewusster mit dem eigenen Erscheinungsbild auseinanderzusetzen"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Achtet in vielen Situationen bewusst auf eine gepflegte und ordentliche eigene Frisur.","punkte":["erscheint überwiegend mit gepflegten Haaren","achtet auf ein ordentliches Gesamtbild","entwickelt mehr Konstanz im eigenen Auftreten","versteht zunehmend die Verbindung zwischen Erscheinung und Professionalität"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Sorgt zuverlässig für ein gepflegtes und stimmiges äußeres Erscheinungsbild.","punkte":["erscheint konstant mit gepflegten Haaren und ordentlicher Frisur","wirkt sauber, strukturiert und bewusst im Auftreten","vermittelt ein stimmiges Gesamtbild","trägt zur Wahrnehmung von Professionalität im Salon bei"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Nutzt das eigene Erscheinungsbild bewusst als Teil der Dienstleistung.","punkte":["erscheint durchgehend gepflegt und sichtbar gestylt","wählt die eigene Frisur bewusst und passend zum Salonstandard","wirkt präsent, ordentlich und professionell","versteht die eigene Ausstrahlung als Teil der Markenwirkung","verkörpert sichtbar das, was im Salon umgesetzt wird"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Verkörpert durch das eigene Erscheinungsbild den Qualitätsanspruch des Salons auf höchstem Niveau.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","nutzt die eigene Frisur als Ausdruck von Stil und Qualität","wirkt inspirierend und authentisch auf Gäste","vermittelt durch das eigene Auftreten Sicherheit und Vertrauen","steht für einen sichtbaren Standard, der Professionalität und Gepflegtheit selbstverständlich macht"]}]},
  {"nr":14,"grundpfeiler":null,"saeule":null,"titel":"Hält die definierten Dresscode-Farben ein (schwarz, weiß oder Erdtöne) und sorgt für ein ruhiges, stimmiges Gesamtbild ohne Muster oder Logos.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, den Dresscode als Teil der eigenen Außenwirkung zu verstehen.","punkte":["entwickelt ein erstes Bewusstsein für Farben und Wirkung","erkennt, dass Kleidung das eigene Auftreten beeinflusst","achtet gelegentlich auf die Vorgaben","beginnt, sich mit dem eigenen Erscheinungsbild auseinanderzusetzen"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Achtet in vielen Situationen bewusst auf die Einhaltung des Dresscodes.","punkte":["erscheint häufig in den definierten Farben","reduziert auffällige Muster oder Logos","entwickelt mehr Sicherheit in der eigenen Kleiderwahl","versteht zunehmend die Wirkung eines ruhigen Erscheinungsbildes"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Hält den Dresscode zuverlässig ein und sorgt für ein stimmiges Auftreten.","punkte":["erscheint konstant in den definierten Farben","verzichtet auf Muster und auffällige Logos","wirkt ruhig und gepflegt im Gesamtbild","trägt zu einem klaren Erscheinungsbild bei"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Nutzt den Dresscode bewusst als Teil der eigenen Personenmarke.","punkte":["wählt Kleidung gezielt und passend zum Stil des Salons","wirkt klar, ruhig und hochwertig im Auftreten","achtet auf ein stimmiges Gesamtbild","versteht Kleidung als Teil der eigenen Wirkung","verkörpert durch das eigene Auftreten Professionalität und Stil"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Verkörpert den Dresscode selbstverständlich und stärkt damit die eigene Ausstrahlung.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","wirkt jederzeit stimmig, reduziert und hochwertig","nutzt Kleidung bewusst als Ausdruck der eigenen Persönlichkeit","achtet intuitiv auf Details im Gesamtbild","strahlt durch das eigene Auftreten Klarheit, Stil und Professionalität aus"]}]},
  {"nr":15,"grundpfeiler":null,"saeule":null,"titel":"Hinterlässt den Waschbereich nach jeder Nutzung sauber und vorbereitet für den nächsten Gast.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, den Zustand des Waschbereichs nach der Nutzung bewusster wahrzunehmen.","punkte":["entwickelt ein erstes Bewusstsein für Ordnung und Sauberkeit","erkennt, dass der Zustand des Waschbereichs den Eindruck beeinflusst","achtet gelegentlich darauf, den Platz sauber zu hinterlassen","beginnt, Verantwortung für den eigenen Arbeitsbereich zu übernehmen"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Achtet in vielen Situationen bewusst darauf, den Waschbereich sauber zu hinterlassen.","punkte":["hinterlässt den Waschbereich häufig ordentlich","entfernt sichtbare Rückstände nach der Nutzung","achtet zunehmend auf Details","entwickelt mehr Routine im Ablauf"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Sorgt zuverlässig für einen sauberen und vorbereiteten Waschbereich.","punkte":["hinterlässt den Waschbereich nach jeder Nutzung sauber","entfernt Rückstände konsequent und sorgfältig","richtet den Platz für den nächsten Gast her","sorgt für einen klaren und ordentlichen Eindruck"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Handelt vorausschauend und sorgt für einen durchgehend sauberen und strukturierten Waschbereich.","punkte":["hinterlässt den Bereich vollständig sauber und vorbereitet","achtet auf Details, die den Unterschied machen","arbeitet ruhig und konsequent im Ablauf","sorgt dafür, dass der nächste Gast direkt starten kann","versteht Sauberkeit als Teil der Dienstleistung"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Schafft durch konsequente Sauberkeit einen durchgehend hohen Standard im Salon.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","sorgt dafür, dass der Waschbereich jederzeit einwandfrei wirkt","erkennt sofort, wenn etwas nicht dem Standard entspricht","handelt selbstverständlich und ohne Verzögerung","trägt dazu bei, dass Sauberkeit im Salon als selbstverständlich wahrgenommen wird"]}]},
  {"nr":16,"grundpfeiler":null,"saeule":null,"titel":"Leistet nach Arbeitsschluss aktiv einen Beitrag zu Ordnung, Sauberkeit und einem vorbereiteten Salon.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, Ordnung und Sauberkeit nach Arbeitsschluss bewusster wahrzunehmen.","punkte":["entwickelt ein erstes Bewusstsein für den Zustand des Salons am Tagesende","erkennt, dass ein vorbereiteter Salon den nächsten Tag beeinflusst","beteiligt sich gelegentlich an einfachen Abschlussaufgaben","beginnt, Verantwortung für gemeinsame Bereiche zu übernehmen"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Beteiligt sich in vielen Situationen aktiv an Ordnung und Sauberkeit nach Arbeitsschluss.","punkte":["übernimmt regelmäßig Aufgaben im Abschluss","achtet bewusster auf Ordnung im eigenen Bereich","unterstützt Kollegen bei gemeinsamen Aufgaben","entwickelt mehr Routine in den Abläufen am Tagesende"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Sorgt zuverlässig für Ordnung und Sauberkeit nach Arbeitsschluss.","punkte":["hinterlässt den eigenen Arbeitsbereich ordentlich und vorbereitet","beteiligt sich selbstverständlich an gemeinsamen Abschlussaufgaben","achtet auf Sauberkeit und Struktur im Salon","trägt zu einem ruhigen und organisierten Tagesabschluss bei"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Handelt vorausschauend und sorgt aktiv für einen klaren und vorbereiteten Salonzustand.","punkte":["erkennt selbstständig, was am Tagesende noch erledigt werden muss","unterstützt aktiv bei Ordnung und Sauberkeit im gesamten Salon","arbeitet strukturiert und zuverlässig bis zum Abschluss","sorgt dafür, dass der Salon vorbereitet und professionell hinterlassen wird","versteht Ordnung und Sauberkeit als Teil der gemeinsamen Verantwortung"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Schafft durch konsequentes Mitdenken einen durchgehend hohen Standard im Salon.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","erkennt frühzeitig offene Aufgaben im Abschluss","sorgt mit dafür, dass der Salon am nächsten Tag direkt arbeitsbereit ist","handelt selbstverständlich im Sinne des gesamten Teams","trägt dazu bei, dass Ordnung und Sauberkeit als fester Qualitätsstandard gelebt werden"]}]},
  {"nr":17,"grundpfeiler":null,"saeule":null,"titel":"Portioniert Farbverbrauch bewusst und dokumentiert verwendete Mengen nachvollziehbar.","video_url":null,"kriterien":[{"stufe":1,"bezeichnung":"1 – Bewusstsein","prozent":"0–25%","leitsatz":"Beginnt, den bewussten Umgang mit Farbverbrauch und Materialeinsatz wahrzunehmen.","punkte":["entwickelt ein erstes Bewusstsein für Farbverbrauch im Alltag","erkennt, dass genaue Mengen Einfluss auf Qualität und Wirtschaftlichkeit haben","achtet gelegentlich auf portioniertes Arbeiten","beginnt, Farbverbrauch bewusster zu dokumentieren"]},{"stufe":2,"bezeichnung":"2 – Aufbau","prozent":"25–50%","leitsatz":"Arbeitet zunehmend strukturierter mit Farbportionierung und Dokumentation.","punkte":["portioniert Farben in vielen Situationen bewusster","notiert verwendete Mengen häufiger nachvollziehbar","entwickelt mehr Sicherheit im Umgang mit Materialeinsatz","erkennt Zusammenhänge zwischen Vorbereitung, Verbrauch und Ergebnis"]},{"stufe":3,"bezeichnung":"3 – Stabilität","prozent":"50–75%","leitsatz":"Arbeitet zuverlässig mit klarer Portionierung und nachvollziehbarer Dokumentation.","punkte":["portioniert Farben konstant passend zum Bedarf","dokumentiert Mengen sauber und nachvollziehbar","vermeidet unnötigen Materialüberschuss","sorgt für Struktur und Nachvollziehbarkeit im Ablauf"]},{"stufe":4,"bezeichnung":"4 – Profi","prozent":"75–100%","leitsatz":"Arbeitet präzise, wirtschaftlich und mit hoher Kontrolle über Materialeinsatz.","punkte":["portioniert Farben vorausschauend und passend zur Dienstleistung","dokumentiert Verbrauch vollständig und klar","arbeitet sauber und organisiert im Umgang mit Material","vermeidet unnötige Verschwendung","versteht bewussten Materialeinsatz als Teil professioneller Arbeitsweise"]},{"stufe":5,"bezeichnung":"5 – High Performer","prozent":"110%","leitsatz":"Verbindet präzises Arbeiten mit verantwortungsbewusstem Materialeinsatz auf höchstem Niveau.","punkte":["erfüllt konsequent alle Kriterien aus Stufe 4","arbeitet konstant kontrolliert und vorausschauend","erkennt Optimierungsmöglichkeiten im Verbrauch frühzeitig","sorgt für hohe Nachvollziehbarkeit und Klarheit im Ablauf","trägt dazu bei, dass bewusster Materialeinsatz als Qualitätsstandard gelebt wird"]}]}
]$daten$::jsonb as j
),
neu as (
  insert into public.verhalten (salon_id, nr, grundpfeiler, saeule, titel, video_url)
  select s.id,
         (v->>'nr')::smallint,
         nullif(v->>'grundpfeiler', ''),
         nullif(v->>'saeule', ''),
         v->>'titel',
         nullif(v->>'video_url', '')
  from public.salons s
  cross join daten
  cross join lateral jsonb_array_elements(daten.j) as v
  where s.name = 'Hammermeister'
  on conflict (salon_id, nr) do nothing
  returning id, nr
)
insert into public.verhalten_kriterien (verhalten_id, stufe, bezeichnung, prozent, leitsatz, punkte)
select neu.id,
       (k->>'stufe')::smallint,
       k->>'bezeichnung',
       k->>'prozent',
       k->>'leitsatz',
       array(select t.x from jsonb_array_elements_text(k->'punkte') with ordinality as t(x, n) order by t.n)
from daten
cross join lateral jsonb_array_elements(daten.j) as v
join neu on neu.nr = (v->>'nr')::smallint
cross join lateral jsonb_array_elements(v->'kriterien') as k
on conflict (verhalten_id, stufe) do nothing;
